/**
 * XDR-JSON (SEP-0051) rendering, decoding and rejection behaviour of the types
 * generated from Stellar-transaction.x.
 */
class XdrJsonTransactionTest {

  @Test
  fun liquidityPoolParametersXdrRoundTripsThroughItsJsonTree() {
    assertRoundTripLiquidityPoolParametersXdr(sampleLiquidityPoolParametersXdr(7, 0))
    assertRoundTripLiquidityPoolParametersXdr(sampleLiquidityPoolParametersXdr(7, SAMPLE_DEPTH))
  }

  private fun assertRoundTripLiquidityPoolParametersXdr(value: LiquidityPoolParametersXdr) {
    val tree = value.toXdrJsonElement()
    val text = LiquidityPoolParametersXdr.fromXdrJsonElement(tree).toXdrJson()
    assertEquals(tree, LiquidityPoolParametersXdr.fromXdrJson(text).toXdrJsonElement())
    assertEquals(text, LiquidityPoolParametersXdr.fromXdrJson(text).toXdrJson())

    val writer = XdrWriter()
    LiquidityPoolParametersXdr.fromXdrJsonElement(tree).encode(writer)
    assertEquals(tree, LiquidityPoolParametersXdr.decode(XdrReader(writer.toByteArray())).toXdrJsonElement())
  }

  @Test
  fun liquidityPoolParametersXdrRendersConstantProductArmAsLiquidityPoolConstantProduct() {
    val value = sampleLiquidityPoolParametersXdrConstantProductArm(7, 0)
    val tree = value.toXdrJsonElement()
    assertEquals(listOf("liquidity_pool_constant_product"), jsonKeys(tree))
    val decoded = LiquidityPoolParametersXdr.fromXdrJsonElement(tree)
    assertEquals(value.discriminant, decoded.discriminant)
    assertEquals(tree, decoded.toXdrJsonElement())
  }

  @Test
  fun liquidityPoolParametersXdrRejectsAnArmItDoesNotDeclare() {
    assertFailsWith<IllegalArgumentException> {
      LiquidityPoolParametersXdr.fromXdrJsonElement(buildJsonObject { put("not_a_name_this_type_declares", JsonNull) })
    }
    assertFailsWith<IllegalArgumentException> {
      LiquidityPoolParametersXdr.fromXdrJsonElement(
        buildJsonObject {
          put("not_a_name_this_type_declares", JsonNull)
          put("not_a_name_this_type_declares_too", JsonNull)
        }
      )
    }
    assertFailsWith<IllegalArgumentException> { LiquidityPoolParametersXdr.fromXdrJsonElement(JsonNull) }
  }


