  @Test
  fun operationBodyXdrRejectsAnArmItDoesNotDeclare() {
    assertFailsWith<IllegalArgumentException> {
      OperationBodyXdr.fromXdrJsonElement(buildJsonObject { put("not_a_name_this_type_declares", JsonNull) })
    }
    assertFailsWith<IllegalArgumentException> {
      OperationBodyXdr.fromXdrJsonElement(
        buildJsonObject {
          put("not_a_name_this_type_declares", JsonNull)
          put("not_a_name_this_type_declares_too", JsonNull)
        }
      )
    }
    assertFailsWith<IllegalArgumentException> {
      OperationBodyXdr.fromXdrJsonElement(JsonPrimitive("not_a_name_this_type_declares"))
    }
    assertFailsWith<IllegalArgumentException> { OperationBodyXdr.fromXdrJsonElement(JsonNull) }
  }


  @Test
  fun operationXdrRoundTripsThroughItsJsonTree() {
