  @Test
  fun transactionResultResultXdrRejectsAnArmItDoesNotDeclare() {
    assertFailsWith<IllegalArgumentException> {
      TransactionResultResultXdr.fromXdrJsonElement(buildJsonObject { put("not_a_name_this_type_declares", JsonNull) })
    }
    assertFailsWith<IllegalArgumentException> {
      TransactionResultResultXdr.fromXdrJsonElement(
        buildJsonObject {
          put("not_a_name_this_type_declares", JsonNull)
          put("not_a_name_this_type_declares_too", JsonNull)
        }
      )
    }
    assertFailsWith<IllegalArgumentException> {
      TransactionResultResultXdr.fromXdrJsonElement(JsonPrimitive("not_a_name_this_type_declares"))
    }
    assertFailsWith<IllegalArgumentException> { TransactionResultResultXdr.fromXdrJsonElement(JsonNull) }
  }


